css:
.launcher-frame > :not(.launcher-bg):not(.game-rail):not(.launcher-topbar) { visibility: hidden !important; }
.launcher-topbar__search, .launcher-topbar__right { visibility: hidden !important; }
.launcher-bg { background: url("https://fixtures.invalid/shell-backdrop.png") center top / cover no-repeat !important; }
.launcher-bg__image, .launcher-bg__front, .launcher-bg__tool { display: none !important; }
